import{_ as s,a8 as t,o as l,c as i,ah as n,K as a}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const v=JSON.parse('{"title":"AI 漫画与视频生成方法论","description":"","frontmatter":{"type":"lesson","scope":"global","created":"2026-09-13T00:00:00.000Z","updated":"2026-09-13T00:00:00.000Z","tags":["lesson","AI生图","AI视频","prompt","角色一致性","即梦","H3","ai-comic","ai-video-clone"]},"headers":[],"relativePath":"vault/Memory/Lessons/AI漫画与视频生成方法论.md","filePath":"vault/Memory/Lessons/AI漫画与视频生成方法论.md","lastUpdated":1789374053000}'),g={name:"vault/Memory/Lessons/AI漫画与视频生成方法论.md"};function c(d,o,h,_,p,m){const r=t("NolebaseGitContributors"),e=t("NolebaseGitChangelog");return l(),i("div",null,[o[0]||(o[0]=n('<h1 id="ai-漫画与视频生成方法论" tabindex="-1">AI 漫画与视频生成方法论 <a class="header-anchor" href="#ai-漫画与视频生成方法论" aria-label="Permalink to “AI 漫画与视频生成方法论”">​</a></h1><blockquote><p>来源：ai-comic（短篇漫画 + 漫剧「灵骸证尸」H3 流水线）与 ai-video-clone（功夫熊猫/犬傲天复刻）实战沉淀，2026-08-26 → 09-01。</p></blockquote><h2 id="提示词与画风" tabindex="-1">提示词与画风 <a class="header-anchor" href="#提示词与画风" aria-label="Permalink to “提示词与画风”">​</a></h2><ol><li><strong>画风固定后缀</strong>：项目启动时把画风描述统一为固定后缀全稿复用（本项目「柔和平涂+漫画网点」），描述不一致直接导致角色变脸/画风漂移。</li><li><strong>风格词陷阱</strong>：<code>3D stylized</code> 类风格词会触发即梦默认可爱 3D 渲染——原片若是扁平几何硬边 2D 插画风，应改「2D 扁平手绘 / graphic novel」+ 明确禁 3D（功夫熊猫 v1 失败根因①）。</li><li><strong>视频提示词信息分层</strong>：只留视觉指令（人物视觉/画风约束/场景构图/逐镜动作微表情/光影）；创作意图、运营参数、性格描述、细分时间戳、画面内字幕、SFX/焦段描述均属冗余占权重。</li><li><strong>H3（MiniMax）黄金结构</strong>：中文剧情 + 英文风格词/负面词混合版（中文对国漫意象解析更准，英文风格与负面词更稳定），对白始终中文。</li><li><strong>负面词底座 + 定制</strong>：<code>avoid realistic, avoid 3D, avoid cell shading, avoid hard shadows</code> + 每镜专属风险负面词；无负面提示词是 v1 失败根因④。</li><li><strong>比例</strong>：单格条漫统一 3:4 竖版且与参考图一致（1:1 人物偏小、16:9 过扁破坏节奏）；三视图 2:1/16:9 横构图、表情集方图。</li></ol><h2 id="角色一致性" tabindex="-1">角色一致性 <a class="header-anchor" href="#角色一致性" aria-label="Permalink to “角色一致性”">​</a></h2><ol start="7"><li><strong>流水线顺序</strong>：先批量生成角色参考图锁定身份（阶段二），再出分镜图——阶段二是确保不变脸的基础。</li><li><strong>多角色同框是变脸重灾区</strong>：须同传全部出场角色参考图，且安排在后期制作。</li><li><strong>参考图强度 0.6-0.7</strong>；手部是崩坏重灾区——道具/手部状态须在动作链中贯穿交代（如「平板始终放茶几」使双手脱空规避异常）。</li><li><strong>识别特征逐项核对</strong>：遮眼刘海、腕表、家徽等是身份锁定关键；AI 常把配饰张冠李戴（林澈被误植仅林昊才戴的银腕表），需负面描述规避。</li><li><strong>图生视频优于文生视频</strong>：图生视频（角色卡生成首帧驱动）能较好保持角色一致性；纯文生视频角色特征被稀释（v1 失败根因③）。</li></ol><h2 id="h3-视频硬约束与失败修复" tabindex="-1">H3 视频硬约束与失败修复 <a class="header-anchor" href="#h3-视频硬约束与失败修复" aria-label="Permalink to “H3 视频硬约束与失败修复”">​</a></h2><ol start="12"><li><strong>硬约束</strong>：16:9 横屏、720p、单角色参考图（场景参考图与人物参考图互斥，槽位有限）；一镜一动作、一运镜、一情绪转折；无状态逐镜独立生成，连续性全靠 prompt 内锚点+参考图——漏写连续性锚点是漂移主风险。</li><li><strong>高失败元素清单</strong>：眼球溶解转场、POV 翻转、多人群像、记忆涌动特效、带表情面部特写——遇之改写为单一稳定动作+起止姿态。</li><li><strong>畸变修复=删冲突元素</strong>：身体长眼睛/双头的根源是 prompt 含冲突元素（身体描述+眼球特写、两主体叠画）；解法=明确主体数量/体态/空间关系+追加负面词+删冲突细节，用剪影和阴影传达恐惧比直接展示更稳。</li><li><strong>镜像陷阱</strong>：提示词 <code>mirror reflection</code> 被模型字面理解生成透明镜像第二人；角色卡含多角度视图也会被误读为多个角色——需单角色锚定声明+消除歧义措辞。</li><li><strong>时长与分镜密度</strong>：单段 GenerateVideo 上限 15s，30s 长视频需分段生成 + ffmpeg concat 合并；15s 内塞 7 镜头节奏过密导致时序一致性崩溃（8 节拍≈12s 较稳）。</li></ol><h2 id="工具选型-2026-08-时点" tabindex="-1">工具选型（2026-08 时点） <a class="header-anchor" href="#工具选型-2026-08-时点" aria-label="Permalink to “工具选型（2026-08 时点）”">​</a></h2><ol start="17"><li><strong>免费生图</strong>：即梦AI 首选（日 60-100 免费积分、中文准、二次元强、图生图角色参考）；豆包与即梦同源可边聊边出图但免费档带「豆包 AI 生成」水印，<strong>水印会经参考图传染到后续生成图</strong>；无水印备选=腾讯混元/元宝（动漫国风）、通义万相（图生图）、可灵/可图（姿态构图稳）、智谱 CogView-3-Flash（批量）；Midjourney 付费出局。</li><li><strong>超写实人像审核风险</strong>：高度写实的原创虚拟角色参考图会被视频生成（seedance）内容审核误判为真实人脸而拒审；风格化/非写实参考图更易通过。</li></ol><h2 id="工程与文档" tabindex="-1">工程与文档 <a class="header-anchor" href="#工程与文档" aria-label="Permalink to “工程与文档”">​</a></h2><ol start="19"><li><strong>Prompt 文档双轨制</strong>：「通用模板」（新项目复用）与「可直接使用的执行稿」（当前项目，含画风后缀+负面词+已填充设定）分离，避免模板被项目细节污染。</li><li><strong>分镜=文字契约</strong>：shot_id、start/end 状态、主动作、运镜、对白、连续性、资产卡引用（13 项 shot contract），无需画分格图；先单集试点再批量。</li><li><strong>Skill 职责单一化</strong>：上游模型管剧本→细纲→分镜→编译 prompt，下游 skill 只管校验→生成→QC→修复→合成（manhua-drama-h3 0.6.0 重构结论）。</li><li><strong>飞书长文档更新用整体 overwrite</strong>，多次 block_replace 会漏 H2 标题致结构混乱；文档内用可 grep 的统一标题格式 + risk_flags 标记。</li><li><strong>koa-connect 包装 Express 中间件会致 ctx 泄漏</strong>，需原生 Koa 重写。</li></ol>',12)),a(r),a(e)])}const k=s(g,[["render",c]]);export{v as __pageData,k as default};
